    {
      "name": "Editing mode visibility",
      "description": "Edit input must be visible and view controls hidden when in editing mode",
      "scenarios": [
        "features/todo-management.feature:Edit input is visible when entering edit mode",
        "features/todo-management.feature:View controls are hidden when editing"
      ]
    },
    {
      "name": "DOM identity perturbation",
      "description": "Browser DOM-identity defect: render() replaces list <li> elements on every mutation, detaching references. Existing toggle scenarios pass in harness but fail in real browser. Perturb at the render() seam to force in-place mutation.",
      "perturbation": {
        "file": "js/app.js",
        "seam": "render() function — todoList.innerHTML = '' rebuilds the entire list, destroying element identity",
        "binding": [
          "features/todo-management.feature:Toggle all todos to completed",
          "features/todo-management.feature:Toggle all clears when all are already completed",
          "features/todo-management.feature:Mark a todo as completed by clicking the checkbox",
          "features/todo-management.feature:Unmark a completed todo by clicking the checkbox again"
        ]
      }
    },
    {
      "name": "Editing save and cancel",
      "scenarios": [
        "features/todo-management.feature:Save edit by pressing Enter",
        "features/todo-management.feature:Save edit on blur",
        "features/todo-management.feature:Destroy todo when edit is cleared to empty",
        "features/todo-management.feature:Destroy todo when edit is whitespace-only",
        "features/todo-management.feature:Cancel edit by pressing Escape"
      ]
    }
  ]
}

